1: import 'package:mad_flutter_practicum/app/app.dart';
2: import 'package:mad_flutter_practicum/domain/domain.dart';
3: 
4: import 'widgets/widgets.dart';
5: 
6: class CurrencyListPage extends StatefulWidget {
7:   const CurrencyListPage({super.key});
8: 
9:   @override
10:   State<CurrencyListPage> createState() => _CurrencyListPageState();
11: }
12: 
13: class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
14:   /// Проектная конвенция: все запросы курса строятся с базовой валютой USD.
15:   static const String _baseCurrency = 'USD';
16: 
17:   static const int _pageSize = 20;
18: 
19:   final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier = ValueNotifier(const []);
20: 
21:   late final AnimationController _fadeController;
22: 
23:   late Future<List<CurrencyModel>> _currencyListFuture;
24: 
25:   List<CurrencyModel> _allCurrencies = [];
26: 
27:   int _nextPage = 0;
28: 
29:   bool _hasMore = false;
30: 
31:   bool _isLoadingMore = false;
32: 
33:   FocusNode? _focusNode;
34: 
35:   @override
36:   void initState() {
37:     super.initState();
38:     _initAnimation();
39:     _initData();
40:   }
41: 
42:   @override
43:   void didChangeDependencies() {
44:     super.didChangeDependencies();
45:     _initFocusListener();
46:   }
47: 
48:   @override
49:   void dispose() {
50:     _focusNode?.removeListener(_onFocusChanged);
51:     _filteredCurrenciesNotifier.dispose();
52:     _fadeController.dispose();
53:     super.dispose();
54:   }
55: 
56:   /// Подписываемся на потерю фокуса экраном: список обновляется свежим запросом.
57:   void _initFocusListener() {
58:     if (_focusNode != null) return;
59: 
60:     final FocusNode focusNode = FocusScope.of(context);
61:     _focusNode = focusNode;
62:     focusNode.addListener(_onFocusChanged);
63:   }
64: 
65:   void _onFocusChanged() {
66:     if (_focusNode?.hasFocus ?? true) return;
67: 
68:     _reloadData();
69:   }
70: 
71:   void _initAnimation() {
72:     _fadeController = AnimationController(
73:       duration: Duration(milliseconds: 400),
74:       vsync: this,
75:     );
76:   }
77: 
78:   void _initData() {
79:     final currencyRepository = context.read<CurrencyRepository>();
80: 
81:     _currencyListFuture = _loadFirstPage(currencyRepository);
82:   }
83: 
84:   /// Свежий запрос списка: сбрасывает пагинацию и повторно запрашивает первую страницу.
85:   void _reloadData() {
86:     final currencyRepository = context.read<CurrencyRepository>();
87:     final Future<List<CurrencyModel>> future = _loadFirstPage(currencyRepository);
88: 
89:     setState(() {
90:       _currencyListFuture = future;
91:     });
92:   }
93: 
94:   Future<List<CurrencyModel>> _loadFirstPage(CurrencyRepository currencyRepository) async {
95:     final CurrencyPage page = await currencyRepository.fetchRates(
96:       const CurrencyPageRequest(base: _baseCurrency, page: 0, pageSize: _pageSize),
97:     );
98:     final List<CurrencyModel> value = page.items;
99: 
100:     _allCurrencies = value;
101:     _nextPage = page.page + 1;
102:     _hasMore = page.hasMore;
103:     _isLoadingMore = false;
104:     _filteredCurrenciesNotifier.value = value;
105: 
106:     _fadeController.forward(); // запускаем анимацию
107: 
108:     await currencyRepository.saveCurrencyList(value);
109: 
110:     return value;
111:   }
112: 
113:   Future<void> _loadMore() async {
114:     if (_isLoadingMore || !_hasMore) return;
115: 
116:     final currencyRepository = context.read<CurrencyRepository>();
117:     final int requestedPage = _nextPage;
118: 
119:     setState(() => _isLoadingMore = true);
120: 
121:     final CurrencyPage page = await currencyRepository.fetchRates(
122:       CurrencyPageRequest(base: _baseCurrency, page: requestedPage, pageSize: _pageSize),
123:     );
124: 
125:     if (!mounted) return;
126: 
127:     final List<CurrencyModel> value = <CurrencyModel>[..._allCurrencies, ...page.items];
128: 
129:     _allCurrencies = value;
130:     _nextPage = page.page + 1;
131:     _hasMore = page.hasMore;
132:     _filteredCurrenciesNotifier.value = value;
133: 
134:     await currencyRepository.saveCurrencyList(page.items);
135: 
136:     if (!mounted) return;
137: 
138:     setState(() => _isLoadingMore = false);
139:   }
140: 
141:   void _filterCurrencies(String query) {
142:     final String lowerQuery = query.toLowerCase();
143:     final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
144:       return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
145:     });
146: 
147:     _filteredCurrenciesNotifier.value = result.toList(growable: false);
148:   }
